  const BAE_RANGES = [[702, 801], [1001, 1100], [1801, 1900], [2401, 2500], [3301, 3400], [5001, 5500], [11847, 12346]];
  let closedAddr = 0, normalAddr = 0;
  const normalAddrList = [];
  for (const [s, e] of BAE_RANGES) {
    for (let r = s; r <= e; r++) {
      const row = ws.getRow(r);
      const addr = row.getCell(7).value;
      const status = row.getCell(2).value || '';
      if (!addr) {
        if (String(status).includes('폐업')) closedAddr++;
        else {
          normalAddr++;
          normalAddrList.push({ r, name: row.getCell(3).value, bizno: row.getCell(4).value, status });
        }
      }
    }
  }
  console.log('주소 공란 중 폐업:', closedAddr, '건, 정상 사업자:', normalAddr, '건');
  console.log('정상 사업자 주소 공란 목록:', JSON.stringify(normalAddrList, null, 2));
}
test();
